const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const t = new Array(2 * n).fill(0);
for (let i = 0; i < n; i++) t[n + i] = tok[2 + i];
for (let i = n - 1; i >= 1; i--) t[i] = t[2 * i] + t[2 * i + 1];
const out = [];
let pos = 2 + n;
for (let j = 0; j < q; j++) {
  const k = tok[pos], x = tok[pos + 1], y = tok[pos + 2];
  pos += 3;
  if (k === 1) {
    let i = x - 1 + n;
    t[i] = y;
    while (i > 1) { i >>= 1; t[i] = t[2 * i] + t[2 * i + 1]; }
  } else {
    let l = x - 1 + n, r = y + n, s = 0;
    while (l < r) {
      if (l & 1) s += t[l++];
      if (r & 1) s += t[--r];
      l >>= 1; r >>= 1;
    }
    out.push(s);
  }
}
console.log(out.join("\n"));

