import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), q = sc.nextInt();
        long[] t = new long[2 * n];
        for (int i = 0; i < n; i++) t[n + i] = sc.nextLong();
        for (int i = n - 1; i >= 1; i--) t[i] = t[2 * i] + t[2 * i + 1];
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < q; j++) {
            int k = sc.nextInt();
            long x = sc.nextLong(), y = sc.nextLong();
            if (k == 1) {
                int i = (int) x - 1 + n;
                t[i] = y;
                while (i > 1) {
                    i >>= 1;
                    t[i] = t[2 * i] + t[2 * i + 1];
                }
            } else {
                int l = (int) x - 1 + n, r = (int) y + n;
                long s = 0;
                while (l < r) {
                    if ((l & 1) == 1) s += t[l++];
                    if ((r & 1) == 1) s += t[--r];
                    l >>= 1;
                    r >>= 1;
                }
                out.append(s).append('\n');
            }
        }
        System.out.print(out);
    }
}

