int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<long long> t(2 * n, 0);
    for (int i = 0; i < n; i++) scanf("%lld", &t[n + i]);
    for (int i = n - 1; i >= 1; i--) t[i] = t[2 * i] + t[2 * i + 1];
    while (q--) {
        int k;
        long long x, y;
        scanf("%d %lld %lld", &k, &x, &y);
        if (k == 1) {
            int i = (int)x - 1 + n;
            t[i] = y;
            while (i > 1) {
                i >>= 1;
                t[i] = t[2 * i] + t[2 * i + 1];
            }
        } else {
            int l = (int)x - 1 + n, r = (int)y + n;
            long long s = 0;
            while (l < r) {
                if (l & 1) s += t[l++];
                if (r & 1) s += t[--r];
                l >>= 1;
                r >>= 1;
            }
            printf("%lld\n", s);
        }
    }
    return 0;
}
